// Parse ket qua LLM (JSON co 2 key: telegram_html, clickup_markdown)
// KHONG throw loi - tra ve co/khong parse duoc de nhanh Debug xu ly rieng, tranh sap ca workflow
const raw = $input.first().json.text || '';
let cleaned = raw.trim();

// Bo markdown code fence neu LLM lo them vao
cleaned = cleaned.replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/, '').trim();

let parsed = null;
let errorMessage = null;

try {
  parsed = JSON.parse(cleaned);
  if (!parsed.telegram_html || !parsed.clickup_markdown) {
    errorMessage = 'JSON thieu key telegram_html hoac clickup_markdown. Nhan duoc key: ' + JSON.stringify(Object.keys(parsed));
    parsed = null;
  }
} catch (e) {
  errorMessage = 'Khong parse duoc JSON tu LLM: ' + e.message;
}

if (parsed) {
  return [{
    json: {
      _parse_ok: true,
      telegram_html: parsed.telegram_html,
      clickup_markdown: parsed.clickup_markdown
    }
  }];
}

// Parse that bai - tra ve day du raw output de debug
return [{
  json: {
    _parse_ok: false,
    error_message: errorMessage,
    raw_output: raw
  }
}];
